import { container } from "../../../container.js";

export async function chat() {

  // DEPS INJECTION
  const auth = container.resolve("whatsAppAuth");

  const { state, saveCreds } = await auth();
  const sock = makeWASocket({
    auth: state,
    printQRInTerminal: true,
  });

  sock.ev.on("creds.update", saveCreds);

  sock.ev.on("connection.update", (update) => {
    const { connection, lastDisconnect, qr } = update;
        console.log("UPDATE:", update);

    if (qr) {
      console.log(" Escaneie o QR:");

      qrcode.generate(qr, {
        small: true,
      });
    }

    if (connection === "open") {
      console.log("✅ WhatsApp conectado");
    }

    if (connection === "close") {
      console.log("❌ Conexão fechada");

      const shouldReconnect =
        lastDisconnect?.error?.output?.statusCode !== DisconnectReason.loggedOut;

      if (shouldReconnect) {
        console.log(" Reconectando...");
        connectWhatsapp();
      }
    }
  });

  sock.ev.on("messages.upsert", ({ messages }) => {
    const msg = messages[0];
    console.log("==>", messages);

    const text = msg.message?.conversation;

    console.log("Mensagem:", text);
  });
}

import { container } from "../../../container.js";
import { makeWASocket } from "@whiskeysockets/baileys";
import { DisconnectReason } from "@whiskeysockets/baileys";
import qrcode from "qrcode-terminal";

export async function chat() {

  // DEPS INJECTION - resolve a função e depois a executa
  const authFn = container.resolve("whatsAppAuth");

  // Se o container retornar a função, chame-a; se retornar o resultado, use diretamente
  const { state, saveCreds } = typeof authFn === 'function' ? await authFn() : authFn;
  const sock = makeWASocket({
    auth: state,
    printQRInTerminal: true,
  });

  sock.ev.on("creds.update", saveCreds);

  sock.ev.on("connection.update", (update) => {
    const { connection, lastDisconnect, qr } = update;
        console.log("UPDATE:", update);

    if (qr) {
      console.log(" Escaneie o QR:");

      qrcode.generate(qr, {
        small: true,
      });
    }

    if (connection === "open") {
      console.log("✅ WhatsApp conectado");
    }

    if (connection === "close") {
      console.log("❌ Conexão fechada");

      const shouldReconnect =
        lastDisconnect?.error?.output?.statusCode !== DisconnectReason.loggedOut;

      if (shouldReconnect) {
        console.log(" Reconectando...");
        connectWhatsapp();
      }
    }
  });

  sock.ev.on("messages.upsert", ({ messages }) => {
    const msg = messages[0];
    console.log("==>", messages);

    const text = msg.message?.conversation;

    console.log("Mensagem:", text);
  });
}

import * as awilix from 'awilix';
import { auth } from "./services/providers/whatsapp/auth.js";
import { whatsappChat } from "./services/providers/whatsapp/chat.js";

export const container = awilix.createContainer({
  injectionMode: awilix.InjectionMode.PROXY,
  strict: true,
});

container.register({
  whatsAppAuth: awilix.asFunction(auth).transient(),
  whatsappChat: awilix.asFunction(whatsappChat).transient(),
});

import * as awilix from 'awilix';
import { auth } from "./services/providers/whatsapp/auth.js";
import { whatsappChat } from "./services/providers/whatsapp/chat.js";

export const container = awilix.createContainer({
  injectionMode: awilix.InjectionMode.PROXY,
  strict: true,
});

container.register({
  whatsAppAuth: awilix.asValue(auth),
  whatsappChat: awilix.asFunction(whatsappChat).transient(),
});

import { sqliteTable, text, integer } from "drizzle-orm/sqlite-core";

export const messages = sqliteTable("messages", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  phone: text("phone").notNull(),
  role: text("role").notNull(),
  content: text("content").notNull(),
  createdAt: integer("created_at", {
    mode: "timestamp",
  }).notNull(),
});

import { sqliteTable, text, integer, real } from "drizzle-orm/sqlite-core";

export const messages = sqliteTable("messages", {
  id: integer("id").primaryKey({ autoIncrement: true }),

  // Identificação
  messageId: text("message_id").unique().notNull(), // ID único do WhatsApp
  phone: text("phone").notNull(), // Telefone do remetente

  // Conteúdo
  content: text("content").notNull(), // Texto da mensagem
  role: text("role").notNull(), // "user" ou "assistant"

  // Tipo de mensagem
  type: text("type").default("text"), // "text", "image", "audio", "video", etc
  mediaUrl: text("media_url"), // URL da mídia se houver

  // Metadados
  isRead: integer("is_read", { mode: "boolean" }).default(false),
  isEdited: integer("is_edited", { mode: "boolean" }).default(false),

  // Timestamps
  createdAt: integer("created_at", { mode: "timestamp" }).notNull(),
  updatedAt: integer("updated_at", { mode: "timestamp" }).notNull(),

  // Status
  status: text("status").default("sent"), // "sent", "delivered", "read", "failed"
});

import express from 'express';
import { container } from './container.js';

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(express.json());

// Resolver controllers do container via injeção de dependência
const userController = container.resolve('userController');
const whatsappController = container.resolve('whatsappController');

// Rotas de Usuários
app.get('/api/users', (req, res) => userController.getAllUsers(req, res));
app.get('/api/users/:id', (req, res) => userController.getUserById(req, res));
app.post('/api/users', (req, res) => userController.createUser(req, res));
app.delete('/api/users/:id', (req, res) => userController.deleteUser(req, res));

// Rotas de WhatsApp
app.post('/api/whatsapp/connect', (req, res) => whatsappController.connect(req, res));
app.get('/api/whatsapp/status', (req, res) => whatsappController.getStatus(req, res));
app.post('/api/whatsapp/reset-auth', (req, res) => whatsappController.resetAuth(req, res));

// Rota de health check
app.get('/health', (req, res) => {
  res.json({ status: 'OK', message: 'Server is running with Awilix DI' });
});

// Iniciar servidor
app.listen(PORT, () => {
  console.log(`✅ Servidor rodando na porta ${PORT}`);
  console.log(` Awilix container foi inicializado e pronto para uso`);
  console.log(` Endpoints WhatsApp: POST /api/whatsapp/connect, GET /api/whatsapp/status`);
});

